    fun assess(spec: LocalModelSpec): ModelEvidence {
        val entry = entries[spec.id]
        return if (entry != null && entry.sha == spec.expectedSha256 &&
            entry.gpu == spec.recommendedGpu && entry.context == spec.contextTokens) entry.evidence
        else ModelEvidence(ModelEvidenceStatus.EXPERIMENTAL,
            "This version or setup has not yet been verified.")
    }
}
